import{_ as e,o as t,c as o,a2 as l}from"./chunks/framework.BWuWLRhz.js";const u=JSON.parse('{"title":"LocalSend ローカル転送設定","description":"","frontmatter":{},"headers":[],"relativePath":"ja-JP/user-guide/settings/localsend.md","filePath":"ja-JP/user-guide/settings/localsend.md","lastUpdated":1785993908000}'),r={name:"ja-JP/user-guide/settings/localsend.md"};function n(s,a,i,d,c,g){return t(),o("div",null,[...a[0]||(a[0]=[l('<h1 id="localsend-ローカル転送設定" tabindex="-1">LocalSend ローカル転送設定 <a class="header-anchor" href="#localsend-ローカル転送設定" aria-label="Permalink to &quot;LocalSend ローカル転送設定&quot;">​</a></h1><p>Lertaro には、公式の <a href="https://localsend.org" target="_blank" rel="noreferrer">LocalSend</a> プロトコルと互換性のあるローカルネットワーク転送機能が統合されています。同一 LAN 内のスマートフォンや PC とファイル、フォルダ、プレーンテキストを相互に転送できます。設定のパスは<strong>設定 → LocalSend</strong>です。</p><h2 id="基本設定" tabindex="-1">基本設定 <a class="header-anchor" href="#基本設定" aria-label="Permalink to &quot;基本設定&quot;">​</a></h2><ul><li><strong>LocalSend ローカル転送を有効化</strong> —— LocalSend 転送サービスのオン/オフを切り替えます。有効化するとトレイメニューに「LocalSend で送信...」項目が表示され、グローバルショートカットにも反応します。</li><li><strong>デバイス名</strong> —— LAN 内の他の LocalSend クライアントから識別されるエイリアス名。デフォルトではマシン名から自動生成されます。</li><li><strong>サービスポート</strong> —— 受信要求を待機する HTTP/HTTPS ポート（既定値は <code>53317</code>）。</li></ul><h2 id="セキュリティと暗号化" tabindex="-1">セキュリティと暗号化 <a class="header-anchor" href="#セキュリティと暗号化" aria-label="Permalink to &quot;セキュリティと暗号化&quot;">​</a></h2><ul><li><strong>暗号化転送 (HTTPS)</strong> —— 有効にすると HTTPS 暗号化接続を使用してデータを転送します（相手デバイスの暗号化サポートが必要です）。</li><li><strong>受信 PIN コード</strong> —— 転送要求時に必要な PIN コード（空欄で無効化）。</li></ul><h2 id="受信と保存" tabindex="-1">受信と保存 <a class="header-anchor" href="#受信と保存" aria-label="Permalink to &quot;受信と保存&quot;">​</a></h2><ul><li><strong>ファイルを自動保存</strong> —— 信頼できるクライアントからのファイルを自動的に受信・保存します。</li><li><strong>保存先フォルダ</strong> —— 受信したファイルの既定の保存先ディレクトリ。</li></ul><h2 id="呼び出しと送信モード" tabindex="-1">呼び出しと送信モード <a class="header-anchor" href="#呼び出しと送信モード" aria-label="Permalink to &quot;呼び出しと送信モード&quot;">​</a></h2><ul><li><strong>ショートカットの呼び出し</strong> —— 既定では <strong><code>Ctrl+S</code></strong>（<a href="./hotkeys-page.html">ショートカット設定</a>で変更可能）またはトレイメニューの「LocalSend で送信...」から呼び出します。</li><li><strong>モード切り替え</strong> —— 送信ウィンドウで [ ファイル / フォルダ送信 ] と [ テキスト送信 ] を切り替えられます。</li></ul>',10)])])}const _=e(r,[["render",n]]);export{u as __pageData,_ as default};
